ROOT = r'c:\xampp\htdocs\MAICC-IFRS9\tools\compliance\standards'
CLONE = 'the scratch clone maiic_ifrs9_wire of 14 October 2026 (a copy of the restructure build\'s database, migrated)'


def edit(name, pairs):
    p = os.path.join(ROOT, name)
    s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        assert s.count(old) == 1, (name, old[:90], s.count(old))
        s = s.replace(old, new, 1)
    open(p, 'w', encoding='utf-8', newline='').write(s)


def row_span(name, start_marker):
    """The full text of the row tuple that begins with start_marker, up to the next row or the list end."""
    s = open(os.path.join(ROOT, name), encoding='utf-8').read()
    i = s.index(start_marker)
    j = s.index('\n (', i + 1)
    k = s.find('\n]', i + 1)
    end = min(x for x in (j, k) if x > 0)
    return s[i:end]


